/* M07 — all-player reveal, human review, ties, round wins, reflection. */
(() => {
  const {$,esc,game:g,on,emit}=LB;
  LB.modules.reflection=()=>{render();on('game:changed',render);};
  function render(){
    const mount=$('#reflection-module');if(!['review','result','finished'].includes(g.phase)){mount.innerHTML='<p>Finish a round to see everyone’s cases.</p>';return;}
    const reviewing=g.phase==='review',finished=g.phase==='finished';
    const winnerNames=(finished?g.matchWinners:g.roundWinners).map(id=>g.players[id].name);
    mount.innerHTML=`<section data-module="07"><span class="module-label">M07 · REVIEW & SCORING</span><div class="result-hero"><img src="assets/pip-sheep.svg" alt="" class="result-pip"><div><span class="stamp">${reviewing?'THE DROP':finished?'FLOCK STARS!':'ROUND '+g.round}</span><h2>${reviewing?'Show your best case!':esc(winnerNames.join(' & '))+(winnerNames.length>1?' share the win!':' wins!')}</h2><p>${reviewing?'Talk it through. Which clues fit?':finished?'You reached '+g.target+' round wins. Baa-rilliant thinking!':'Round winner +1. Tied players each get +1.'}</p></div></div>${reviewing?`<p class="review-tip">✓ Matching clues are checked. Agree together before changing them.</p>`:''}<div class="cases-grid">${g.cases.map(c=>{
      const p=g.players[c.playerId];return `<article class="case-result"><div class="case-result-head"><span class="player-dot dot-${p.id}">${p.id+1}</span><h3>${esc(p.name)}</h3><span class="stamp small-stamp">${c.side.toUpperCase()}</span><strong id="total-${p.id}" class="evidence-total">${g.total(c)} pts</strong></div>${c.reasoning?`<p class="readable case-explanation" id="case-explanation-${p.id}">${esc(c.reasoning)}</p><button class="text-button" data-read-case="${p.id}">Listen to the explanation</button>`:'<p class="small-print">Tell the group why these clues fit.</p>'}<ul class="review-cards">${c.cards.map((card,i)=>`<li><label>${reviewing?`<input type="checkbox" data-count-player="${p.id}" data-count-index="${i}" ${c.counted[i]?'checked':''} aria-label="Count ${esc(card.title)} for ${esc(p.name)}">`:`<span aria-hidden="true">${c.counted[i]?'✓':'○'}</span>`}<span><strong>${esc(card.title)} <b>+${card.points}</b></strong><span id="review-card-${p.id}-${i}" class="readable">${esc(card.text)}</span>${reviewing?`<small>${g.applies(card)?'Matches shown news / context':'Matching context is not shown'}</small>`:''}</span></label><button class="text-button" data-read-review="${p.id}:${i}">Listen<span class="sr-only"> to ${esc(card.title)} for ${esc(p.name)}</span></button></li>`).join('')||'<li>No evidence · 0 points</li>'}</ul><small>Pip hints: ${c.guideUses.length} · No effect on points</small></article>`;
    }).join('')}</div>${reviewing?'<button class="button primary full" id="award-round">We agree · score the round ★</button>':`<div class="scoreboard" aria-label="Match scores">${g.players.map(p=>`<div><span class="player-dot dot-${p.id}">${p.id+1}</span><strong>${esc(p.name)}</strong><b>${p.score}</b><small>round wins</small></div>`).join('')}</div><details class="reflection-note"><summary>One last thought…</summary><label for="round-reflection">Did a clue or Pip’s hint change your mind?</label><textarea id="round-reflection" maxlength="1000" placeholder="Talk together, or jot down a thought.">${esc(g.history.at(-1)?.reflection||'')}</textarea><p class="small-print">Reading and voice tools are access tools, not AI help.</p></details><div class="button-row"><button class="button primary" id="next-round">${finished?'Play again':'Next round →'}</button><button class="button" id="export-game">Save our game ↓</button></div>`}</section>`;
    document.querySelectorAll('[data-count-player]').forEach(input=>input.onchange=()=>{g.count(Number(input.dataset.countPlayer),Number(input.dataset.countIndex),input.checked);const c=g.cases.find(c=>c.playerId===Number(input.dataset.countPlayer));$('#total-'+c.playerId).textContent=g.total(c)+' pts';LB.announce(g.players[c.playerId].name+': '+g.total(c)+' evidence points.');});
    document.querySelectorAll('[data-read-case]').forEach(b=>b.onclick=()=>{const c=g.cases.find(c=>c.playerId===Number(b.dataset.readCase));emit('reading:evidence',{text:c.reasoning,node:$('#case-explanation-'+c.playerId)});});
    document.querySelectorAll('[data-read-review]').forEach(b=>b.onclick=()=>{const [pid,i]=b.dataset.readReview.split(':').map(Number),c=g.cases.find(c=>c.playerId===pid);emit('reading:evidence',{text:c.cards[i].text,node:$('#review-card-'+pid+'-'+i)});});
    if(reviewing)$('#award-round').onclick=()=>LB.run(()=>g.award(),'Round scored!');
    else {
      $('#round-reflection').oninput=e=>{g.history.at(-1).reflection=e.target.value;};
      $('#next-round').onclick=()=>finished?LB.ask({title:'Play again?',text:'Start a fresh match with the same flock.',confirm:'Deal again',action:()=>LB.run(()=>g.start(g.players.map(p=>p.name),g.target),'New match!')}):LB.run(()=>g.nextRound(),'New round. Pass the device.');
      $('#export-game').onclick=()=>LB.download('lamboozled-game.txt','LAMBOOZLED! — sample-card game\n\n'+g.players.map(p=>p.name+': '+p.score+' round wins').join('\n')+'\n\n'+g.history.map(r=>'ROUND '+r.round+' — '+r.story+'\n'+r.cases.map(c=>g.players[c.playerId].name+': '+c.side.toUpperCase()+', '+c.total+' evidence points; Pip hints '+c.guideUses.length+'\n'+(c.reasoning||'Spoken explanation')).join('\n')+'\nReflection: '+(r.reflection||'Discussed aloud')).join('\n\n'));
    }
  }
})();
